pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        address operator = address(0x1234);
        vm.prank(operator);
        c.initialize();


        bool ok;
        bytes memory encodedParameters = abi.encode(address(0));

        try c.create(encodedParameters, operator) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
